def test_generate_and_unlink(link_api):
    """
    Generate a link code, check the fields the service fills in, generate a second code for the
    same tenant, then unlink both codes.
    """
    tenant = gcp_tenant_id()
    logger.info(f"[LINK] Generating a link code for gcp_tenant_id={tenant}")

    # ── Step 1: Generate ──────────────────────────────────────────────────────
    start = time.time()
    res = link_api.generate_link_code(
        link_generate_request=LinkGenerateRequest(gcp_tenant_id=tenant),
        x_panw_region=CNGFW_GCP_REGION,
    )
    assert res is not None, "Generate response should not be None"
    assert res.response_status is not None, "ResponseStatus should not be None"
    assert res.response_status.error_code == 0, "ErrorCode should be 0 on success"
    assert res.response_status.code == "OK", "ResponseStatus.Code should be OK on success"
    assert res.response is not None, "Generate result should not be None"

    result = res.response
    first_code = result.code
    assert first_code, "Generate must return a link code"
    # The TSG comes from the access token, and the service looks up the TSG's CSP account.
    assert result.tsgid and re.fullmatch(r"[0-9]+", result.tsgid), (
        f"TSGID should be the numeric TSG of the access token, got {result.tsgid!r}"
    )
    assert result.cspid, "CSPID should be filled in by the service"
    # Codes expire 48 hours after they are generated.
    assert abs(result.expires_at - (start + CODE_TTL_SECONDS)) < 60 * 60, (
        f"ExpiresAt should be about 48 hours from now, got {result.expires_at}"
    )
    logger.info(
        f"[LINK] Generate OK: tsg_id={result.tsgid} csp_id={result.cspid} expires_at={result.expires_at}"
    )

    # ── Step 2: Generate again for the same tenant ───────────────────────────
    # Each firewall endpoint is created with its own code, so every call mints a fresh one.
    res2 = link_api.generate_link_code(
        link_generate_request=LinkGenerateRequest(gcp_tenant_id=tenant),
        x_panw_region=CNGFW_GCP_REGION,
    )
    assert res2.response is not None, "Second generate result should not be None"
    second_code = res2.response.code
    assert second_code, "Second generate must return a link code"
    assert second_code != first_code, "Each generate call should mint a new code"

    # ── Step 3: Unlink ────────────────────────────────────────────────────────
    # Neither code was redeemed, so there is no binding to retire, but the call still succeeds.
    # There is no cleanup to do for the same reason: an unused code can only expire.
    for code in (first_code, second_code):
        unlink_res = link_api.unlink_tenant(
            link_unlink_request=LinkUnlinkRequest(code=code, gcp_tenant_id=tenant),
            x_panw_region=CNGFW_GCP_REGION,
        )
        assert unlink_res is not None, "Unlink response should not be None"
        assert unlink_res.response_status is not None, "ResponseStatus should not be None"
        assert unlink_res.response_status.code == "OK", "ResponseStatus.Code should be OK on success"
        assert unlink_res.response is not None, "Unlink result should not be None"
        assert unlink_res.response.gcp_tenant_id == tenant, "Unlink should echo the GCP tenant"
        assert unlink_res.response.unlinked is True, "Unlinked should be true"
    logger.info(f"[LINK] Unlink OK: gcp_tenant_id={tenant}")


def test_generate_rejects_invalid_tenant(link_api):
    """
    An invalid GCP tenant ID is rejected by the SDK before it is sent, and by the service when the
    SDK's validation is bypassed.
    """
    with pytest.raises(ValidationError):
        LinkGenerateRequest(gcp_tenant_id="Invalid_Project")

    # model_construct skips validation, so the request reaches the service as written.
    with pytest.raises(BadRequestError) as exc_info:
        link_api.generate_link_code(
            link_generate_request=LinkGenerateRequest.model_construct(gcp_tenant_id="Invalid_Project"),
            x_panw_region=CNGFW_GCP_REGION,
        )
    assert exc_info.value.http_status_code == 400, "Expected 400 for an invalid GCP tenant ID"
    assert link_error_code(exc_info.value) == "FIELD_INVALID", "Expected FIELD_INVALID"
    logger.info(f"[LINK] Invalid tenant correctly rejected: {exc_info.value}")


def test_unlink_requires_code(link_api):
    """Unlink rejects a request without a link code: the code identifies the binding to retire."""
    with pytest.raises(BadRequestError) as exc_info:
        link_api.unlink_tenant(
            link_unlink_request=LinkUnlinkRequest(code="", gcp_tenant_id=gcp_tenant_id()),
            x_panw_region=CNGFW_GCP_REGION,
        )
    assert exc_info.value.http_status_code == 400, "Expected 400 for a missing code"
    assert link_error_code(exc_info.value) == "FIELD_MISSING", "Expected FIELD_MISSING"
    logger.info(f"[LINK] Missing code correctly rejected: {exc_info.value}")
